#!/usr/bin/env bash
# mobile-perf.test.sh — RichConnect's speed and battery measurement tool (richos/mobile/perf, PRD
# 2026-09-24 §9 step 1): its parsers against output captured from the Android emulator, the whole
# Android run against a scripted adb (refusing a stale build or a misnamed device), and on iOS the
# parsers, the presentation join, the export re-read and the trace series against synthetic exports,
# plus the app's mark names and one-shot marker in PerformanceMarks.swift. Nothing builds, boots or opens a window.
# run-tests: no-host-screen: parsers and a scripted adb only; no emulator, simulator or window
# run-tests: inputs richos/engine/scripts/lib/machine_settings.py richos/mobile/machine_storage.py richos/mobile/cli/machine-settings.mjs richos/mobile/perf richos/mobile/native-android/bin/randroid richos/mobile/native-android/bin/apk-install.sh richos/mobile/native-ios/bin/rios richos/mobile/native-ios/App/Platform/PerformanceMarks.swift richos/mobile/native-ios/Core/Sources/RichOSCLI/Simulator.swift richos/mobile/native-ios/Core/Package.swift richos/mobile/native-ios/project.yml richos/mobile/native-ios/Release/platform.yml richos/mobile/native-ios/Tools/physical-device.mjs richos/mobile/native-ios/UITests/PhysicalDeviceTests.swift richos/mobile/native-android/app/build.gradle.kts richos/mobile/native-android/app/src/main/AndroidManifest.xml richos/mobile/physical.py richos/mobile/phone_net.py richos/app/scripts/qa/phone-ios.py richos/mobile/native-ios/Core/Sources/RichOSPerfSeed richos/mobile/native-ios/App richos/mobile/native-ios/DevBridge richos/mobile/native-ios/NotificationService richos/mobile/native-ios/ShareExtension docs/verification/2026-09-24-richconnect-android-perf-baseline richos/app/scripts/mobile-perf.test.sh richos/app/scripts/mobile-perf.test.py
# run-tests: covers richos/mobile/machine_storage.py richos/mobile/perf/phone_changes.py richos/mobile/perf/test_verdict.py richos/mobile/perf/test_copy.py richos/mobile/perf/bench/bench.py richos/mobile/perf/bench/test_bench.py richos/mobile/perf/perf.py richos/mobile/perf/benchmark.py richos/mobile/perf/condition.py richos/mobile/native-android/bin/apk-install.sh richos/mobile/perf/perfcore.py richos/mobile/perf/android.py richos/mobile/perf/ios.py richos/mobile/native-ios/App/Platform/PerformanceMarks.swift richos/mobile/native-ios/Core/Sources/RichOSPerfSeed/PerfSeed.swift docs/verification/2026-09-24-richconnect-android-perf-baseline/record.json docs/verification/2026-09-24-richconnect-android-perf-baseline/parts/part1-cold-idle.json docs/verification/2026-09-24-richconnect-android-perf-baseline/parts/part2-warm-scroll-tap.json docs/verification/2026-09-24-richconnect-android-perf-baseline/parts/part3-typing.json docs/verification/2026-09-24-richconnect-android-perf-baseline/parts/part4-stream-background-pairing.json
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PYTHONDONTWRITEBYTECODE=1 python3 "$here/mobile-perf.test.py"
# `randroid device bench`: argument handling, the verb refusal and the parsers (no phone)
PYTHONDONTWRITEBYTECODE=1 python3 "$here/../../mobile/perf/bench/test_bench.py"
# `device perf` prints the §104 cold and warm verdicts; no `None.evidence` default
PYTHONDONTWRITEBYTECODE=1 python3 "$here/../../mobile/perf/test_verdict.py"
